import * as T from 'three';import{block,VoxelAssetFactory}from'./VoxelAssetFactory.js';export function label(text){const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');x.fillStyle='#ffffff';x.fillRect(0,0,512,128);x.fillStyle='#254963';x.font='bold 40px sans-serif';x.textAlign='center';x.fillText(text,256,80);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c)}));s.scale.set(7,1.75,1);return s}export class MapPropBuilder{constructor(group){this.group=group;this.solids=[];this.pads=[]}platform(x,y,z,w,d,color=0x8bdb9b){const m=block(this.group,color,x,y,z,w,.6,d);this.solids.push({x,z,y:y+.3,w,d});return m}pad(x,z,icon,color,fn){const g=new T.Group();g.position.set(x,0,z);block(g,color,0,.12,0,3,.24,3);const l=label(icon);l.position.y=3;g.add(l);this.group.add(g);this.pads.push({x,z,fn,cool:0});return g}decorate(){for(let i=0;i<30;i++){const t=VoxelAssetFactory.tree();t.position.set(Math.sin(i*2.4)*(30+i%4*5),0,Math.cos(i*2.4)*(30+i%4*5));this.group.add(t)}for(let i=0;i<18;i++)block(this.group,0xffffff,-35+i*4,1,-34,.2,2,.2);block(this.group,0xffe9bf,0,1.5,-34,70,.2,.2)}machine(x,z,name){const g=new T.Group();g.position.set(x,0,z);block(g,0x6983c1,0,.3,0,5,.6,3);for(const a of [-1.3,1.3]){const glass=new T.Mesh(new T.CylinderGeometry(.65,.65,2,16),new T.MeshPhysicalMaterial({color:0x89edff,transparent:true,opacity:.35,roughness:.1}));glass.position.set(a,1.6,0);g.add(glass);block(g,0x84f5ed,a,2.7,0,1.6,.25,1.6)}const l=label(name);l.position.y=4;g.add(l);this.group.add(g);return g}}
